import { DeepbookV3Config } from '@cetusprotocol/aggregator-sdk'
import { StateCreator, create } from 'zustand'
import { persist } from 'zustand/middleware'

interface WebConfigState {
  /**
   * 用户许可
   */
  isTerm: boolean
  setIsTerm: (isTerm: boolean) => void

  isBuyCryptoConfirm: boolean
  setIsBuyCryptoConfirm: (isTerm: boolean) => void

  providers: string[]
  setProviders: (providers: string[]) => void

  deepbookV3Config: DeepbookV3Config | null
  setDeepbookV3Config: (deepbookV3Config: DeepbookV3Config | null) => void

  isSwapWidgetDisplay: boolean
  setIsSwapWidgetDisplay: (isSwapWidgetDisplay: boolean) => void

  showSwapWidgetTips: boolean
  setShowSwapWidgetTips: (showSwapWidgetTips: boolean) => void
}

const store: StateCreator<WebConfigState> = (set, get) => ({
  deepbookV3Config: null,
  providers: ['CETUS'],
  isBuyCryptoConfirm: false,
  setIsBuyCryptoConfirm: (isBuyCryptoConfirm: boolean) => {
    set(() => ({
      isBuyCryptoConfirm
    }))
  },
  isTerm: false,
  setIsTerm: (isTerm: boolean) => {
    set(() => ({
      isTerm
    }))
  },
  setProviders: providers => {
    set(() => ({
      providers
    }))
  },
  setDeepbookV3Config: deepbookV3Config => {
    set(() => ({
      deepbookV3Config
    }))
  },
  isSwapWidgetDisplay: true,
  setIsSwapWidgetDisplay: (isSwapWidgetDisplay: boolean) => {
    set(() => ({
      isSwapWidgetDisplay
    }))
  },
  showSwapWidgetTips: true,
  setShowSwapWidgetTips: (showSwapWidgetTips: boolean) => {
    set(() => ({
      showSwapWidgetTips
    }))
  }
})

const useWebConfigStore = create(persist(store, { name: 'useWebConfigStore', version: 3 }))
export default useWebConfigStore
