import numbro from 'numbro'
import { isNumeric } from './assertion'
import { Decimal } from './decimal'

export const d = (value?: Decimal.Value | undefined): Decimal.Instance => {
  if (Decimal.isDecimal(value)) {
    return value as Decimal
  }

  return new Decimal(typeof value === 'undefined' || value === 'undefined' || !value ? 0 : value)
}

// Add thousands separator to numbers
export const addComma = (value: string | number) => {
  // try {
  //   const string = d(value).gt(1) ? numbro(value).format({ thousandSeparated: true, exponential: false }).toString() : value // '1,000'
  //   return string
  // } catch (error) {
  //   return value
  // }

  // try {
  //   const str = String(value)
  //   const [integerPart, decimalPart] = str.split('.')

  //   let formattedInteger = ''
  //   let count = 0

  //   for (let i = integerPart.length - 1; i >= 0; i--) {
  //     formattedInteger = integerPart[i] + formattedInteger
  //     count++
  //     if (count % 3 === 0 && i !== 0) {
  //       formattedInteger = ',' + formattedInteger
  //     }
  //   }

  //   return decimalPart ? `${formattedInteger}.${decimalPart}` : formattedInteger
  // } catch (error) {
  //   return value
  // }

  try {
    const str = String(value)
    // 匹配包含小数点的数字和不包含小数点的数字
    return str.replace(/\d+(?:\.\d+)?/g, match => {
      if (match.includes('.')) {
        // 处理包含小数点的数字
        const [integer, decimal] = match.split('.')
        let formattedInteger = ''
        let count = 0

        for (let i = integer.length - 1; i >= 0; i--) {
          formattedInteger = integer[i] + formattedInteger
          count++
          if (count % 3 === 0 && i !== 0) {
            formattedInteger = ',' + formattedInteger
          }
        }

        return `${formattedInteger}.${decimal}`
      } else {
        // 处理不包含小数点的数字
        let formatted = ''
        let count = 0

        for (let i = match.length - 1; i >= 0; i--) {
          formatted = match[i] + formatted
          count++
          if (count % 3 === 0 && i !== 0) {
            formatted = ',' + formatted
          }
        }

        return formatted
      }
    })
  } catch (error) {
    return String(value)
  }
}

export const addCommaWithNoMantissa = (value: string | number) => {
  try {
    const string = d(value).gt(1) ? numbro(value).format({ thousandSeparated: true, mantissa: 0 }) : value // '1,000'
    return string
  } catch (error) {
    return value
  }
}

export const unformat = (value: string) => {
  if (value === '--') return '--'
  if (!value) return value
  return numbro.unformat(value)
}

// rounding
export const fixRounding = (value: string | number, decimal: number) => {
  const result = d(value).toDP(decimal, Decimal.ROUND_HALF_DOWN).toString()
  return result
}

export const fixNumber = (value: string | number, decimal: number, rounding: Decimal.Rounding) => {
  const result = d(value).toDP(Number(decimal), rounding).toString()
  return result
}

// round down
export const fixDown = (value: string | number, decimal: number) => {
  try {
    const result = d(value).toDP(decimal, Decimal.ROUND_DOWN).toString()
    return result
  } catch (error) {
    return String(value)
  }
}

// round up
export const fixUp = (value: string | number, decimal: number) => {
  const result = d(value).toDP(decimal, Decimal.ROUND_UP).toString()
  return result
}

// 去除小数位后面的0
export const removeDecimalZeros = (value: string) => {
  // 将字符串中所有非数字非小数点的字符都替换为空字符串，并且去除了连续的小数点，保留了小数点后的内容。
  try {
    return d(value.replace(/[^\d.]+|(\..*)\./g, '$1')).toString()
  } catch (error) {
    return ''
  }
}

export function getGtZeroIndex(value: string) {
  let i = 0
  if (value) {
    while (i < value.length) {
      if (d(value[i]).gt(0)) {
        return i
      }
      i++
    }
  }
  return 0
}

