import { SingleCoinImage } from '@cetus/ui-kit'
import { Box, CenterProps } from '@chakra-ui/react'

interface TokenAvatarProps {
  size?: string
  src: string
  coin_type?: string
  variant?: 'border' | ''
  style?: CenterProps
  showTag?: boolean
  tag_url?: string
  placeholderTagImg?: string
}

function TokenAvatar({ coin_type, size = '38px', src, variant, style = {}, showTag, tag_url, placeholderTagImg }: TokenAvatarProps) {
  return (
    <Box w={size} h={size} minW={size} minH={size} maxW={size} maxH={size} borderRadius="50%">
      <SingleCoinImage
        variant={variant}
        imageUrl={src}
        w={size}
        h={size}
        borderRadius="50%"
        coinType={coin_type}
        p="4px"
        imgBoxStyle={style}
        showTag={showTag}
        tag_url={tag_url}
        placeholderTagImg={placeholderTagImg}
      />
    </Box>
  )
}

export default TokenAvatar
