import useExplorer from '@cetus/hooks/src/useExplorer'
import { defaultExplorers } from '@cetus/types'
import { ToastType } from '@cetus/types/src/common-types'
import { Icon } from '@cetus/ui-kit'
import { d } from '@cetusprotocol/common-sdk'
import { Center, HStack, Image, Text, VStack } from '@chakra-ui/react'
import { useMemo } from 'react'
import { ToastDescription } from './ToastDescription'
import { ToastTitle } from './ToastTitle'

type ToastProps = {
  onClose?: () => void
} & ToastType

export default function Toast(props: ToastProps) {
  const { status = 'confirmation', link, tx, getShowInfo, actionType, executeTime, linkLabel = 'View transaction', onClose } = props
  const { getExplorerUrl } = useExplorer()
  // console.log('🚀 ~ file: Toast.tsx:12 ~ Toast ~ props:', props)

  const showInfo = useMemo(() => {
    if (getShowInfo) {
      return getShowInfo(status)
    }
    return undefined
  }, [status])

  return (
    <HStack
      w={{ base: 'calc(100vw - 16px)', lg: '360px' }}
      minW={{ base: 'calc(100vw - 16px)', lg: '360px' }}
      maxW={{ base: 'calc(100vw - 16px)', lg: '420px' }}
      bg="background"
      border="1px"
      borderColor="border"
      borderRadius="12px"
      p="16px"
      gap="16px"
      justify="space-between"
      alignItems="flex-start"
    >
      <VStack alignItems="start">
        {/* 标题 */}
        <ToastTitle info={showInfo} status={status} />

        {/* 描述 */}
        {<ToastDescription info={showInfo} status={status} tx={tx} />}

        {/* 区块游览器 */}
        {(status !== 'submitted' || showInfo?.showSubmittedToast) && link && (
          <HStack alignItems="center" cursor="pointer" onClick={() => window.open(link, '_blank')}>
            <Text color="primary" fontSize="12px" mb="2px">
              View on Explorer
            </Text>
            <Icon xlinkHref="#icon-icon_link1" svgFill="primary" />
          </HStack>
        )}
        {status !== 'submitted' && !link && tx && (
          <HStack>
            {actionType === 'swap' && executeTime && executeTime > 0 ? (
              <Text fontSize="12px">{`Txn finalized in ${d(executeTime).div(1000).toString()}s! View Transaction`}</Text>
            ) : (
              <Text fontSize="12px">View on Explorer</Text>
            )}

            {defaultExplorers.map(explorer => {
              return (
                <Image
                  onClick={e => {
                    window.open(getExplorerUrl(tx, 'tx', explorer), '_blank')
                  }}
                  cursor="pointer"
                  key={explorer.name}
                  src={explorer.img}
                  alt="SVG Image"
                  boxSize="16px"
                  objectFit="cover"
                  borderRadius="8px"
                />
              )
            })}
          </HStack>
        )}
      </VStack>

      {/* 关闭按钮 */}
      <Center onClick={onClose}>
        <Icon xlinkHref="#icon-icon_close" variant="gray" />
      </Center>
    </HStack>
  )
}
