import { NOTIFI_SIGNATURE, VariousTokensTable } from '@cetus/utils'
import { Types } from '@notifi-network/notifi-graphql'
import { create, StateCreator } from 'zustand'

interface notifiState {
  notifiAlerts: Types.AlertFragmentFragment[]
  setNotifiAlerts: (notifiAlerts: Types.AlertFragmentFragment[]) => void

  notifiSourceGroups: Types.SourceGroupFragmentFragment[]
  setNotifiSourceGroups: (notifiSourceGroups: Types.SourceGroupFragmentFragment[]) => void

  notifiSources: Types.Source[]
  setNotifiSources: (notifiSources: Types.Source[]) => void

  isChecked: boolean
  setIsChecked: (status: boolean) => void

  isShowNotifi: boolean
  setIsShowNotifi: (status: boolean) => void

  notifiClient: any
  setNotifiClient: (client: any) => void

  notifiSubscriptionLoading: boolean
  setNotifiSubscriptionLoading: (status: boolean) => void

  notifiStatus: string
  setNotifiStatus: (value: string) => void

  defaultTargetGroup: ReadonlyArray<Types.TargetGroupFragmentFragment>
  setDefaultTargetGroup: (notifiTargetGroup: ReadonlyArray<Types.TargetGroupFragmentFragment>) => void

  notifiAccountAddress: string
  setNotifiAccountAddress: (value: string) => void

  notifiLoginLoading: boolean
  setNotifiLoginLoading: (value: boolean) => void

  emailTarget: object
  setEmailTarget: (emailTarget: object) => void

  telegramTarget: object
  setTelegramTarget: (telegramTarget: object) => void

  smsTarget: object
  setSmsTarget: (smsTarget: object) => void
}

const store: StateCreator<notifiState> = (set, get) => ({
  notifiAlerts: [],
  setNotifiAlerts: (notifiAlerts: Types.AlertFragmentFragment[]) => {
    set(() => ({
      notifiAlerts
    }))
  },
  notifiSourceGroups: [],
  setNotifiSourceGroups: (notifiSourceGroups: Types.SourceGroupFragmentFragment[]) => {
    set(() => ({
      notifiSourceGroups
    }))
  },
  notifiSources: [],
  setNotifiSources: (notifiSources: Types.Source[]) => {
    set(() => ({
      notifiSources
    }))
  },
  isChecked: false,
  setIsChecked: (status: boolean) => {
    set(() => ({
      isChecked: status
    }))
  },
  isShowNotifi: false,
  setIsShowNotifi: (isShowNotifi: boolean) => {
    set(() => ({
      isShowNotifi
    }))
  },
  notifiSubscriptionLoading: false,
  setNotifiSubscriptionLoading: (notifiSubscriptionLoading: boolean) => {
    set(() => ({
      notifiSubscriptionLoading
    }))
  },
  notifiLoginLoading: false,
  setNotifiLoginLoading: (notifiLoginLoading: boolean) => {
    set(() => ({
      notifiLoginLoading
    }))
  },
  notifiClient: {},
  setNotifiClient: (notifiClient: any) => {
    set(() => ({
      notifiClient
    }))
  },
  notifiStatus: '',
  setNotifiStatus: (notifiStatus: any) => {
    set(() => ({
      notifiStatus
    }))
  },
  defaultTargetGroup: [],
  setDefaultTargetGroup: (defaultTargetGroup: ReadonlyArray<Types.TargetGroupFragmentFragment>) => {
    set(() => ({
      defaultTargetGroup
    }))
  },
  notifiAccountAddress: '',
  setNotifiAccountAddress: (notifiAccountAddress: string) => {
    set(() => ({
      notifiAccountAddress
    }))
  },
  emailTarget: {},
  setEmailTarget: emailTarget => {
    set(() => ({
      emailTarget
    }))
  },
  telegramTarget: {},
  setTelegramTarget: telegramTarget => {
    set(() => ({
      telegramTarget
    }))
  },
  smsTarget: {},
  setSmsTarget: smsTarget => {
    set(() => ({
      smsTarget
    }))
  }
})

const useNotifiStore = create(store)
export default useNotifiStore

